import Image from "next/image";
import Link from "next/link";
import { MapPin, Clock, Phone, Mail, Globe, Star, ChevronDown } from "lucide-react";
import type { BusinessAdData } from "@/lib/validators/template-schemas";

interface BusinessProps { data: BusinessAdData; accentColor?: string; }

interface BizProps { data: BusinessAdData; accentColor?: string; }

// ─────────────────────────────────────────────────────────────────────────────
// SHARED HELPERS
// ─────────────────────────────────────────────────────────────────────────────

function contactHref(type: string, value: string) {
  if (type === "email") return `mailto:${value}`;
  if (type === "phone") return `tel:${value.replace(/\s/g, "")}`;
  if (type === "website") return value.startsWith("http") ? value : `https://${value}`;
  return "#";
}

function StarRating({ rating }: { rating: number }) {
  return (
    <div className="flex">
      {Array.from({ length: 5 }).map((_, i) => (
        <span key={i} className={i < rating ? "text-amber-400" : "text-neutral-700"}>★</span>
      ))}
    </div>
  );
}
export function EmpireBusiness({ data, accentColor = "#7c3aed" }: BizProps) {
  const {
    businessName, tagline, description, logoUrl, heroImageUrl,
    services, contacts, testimonials, socialLinks, primaryCtaLabel, primaryCtaUrl,
    certifications, founded, industry, employeeCount,
  } = data;

  return (
    <main className="min-h-screen bg-white text-zinc-900">

      {/* Fixed nav */}
      <header className="fixed top-0 z-50 w-full border-b border-zinc-100 bg-white/95 backdrop-blur-sm shadow-sm">
        <div className="mx-auto flex max-w-6xl items-center justify-between px-6 py-4">
          {logoUrl ? (
            <Image src={logoUrl} alt={businessName} width={110} height={36} className="h-9 w-auto object-contain" />
          ) : (
            <span className="text-lg font-black">{businessName}</span>
          )}
          <nav className="hidden items-center gap-8 md:flex">
            {["Services", "About", "Clients", "Contact"].map(item => (
              <a key={item} href={`#${item.toLowerCase()}`}
                className="text-sm font-medium text-zinc-500 hover:text-zinc-900 transition-colors">
                {item}
              </a>
            ))}
          </nav>
          <a href={primaryCtaUrl} className="rounded-xl px-5 py-2.5 text-sm font-bold text-white shadow-lg transition-all hover:opacity-90"
            style={{ background: `linear-gradient(135deg, ${accentColor}, ${accentColor}cc)`, boxShadow: `0 4px 16px ${accentColor}35` }}>
            {primaryCtaLabel}
          </a>
        </div>
      </header>

      {/* Hero */}
      <section className="relative pt-20 min-h-[90vh] flex items-center overflow-hidden">
        {heroImageUrl ? (
          <>
            <Image src={heroImageUrl} alt={businessName} fill className="object-cover" sizes="100vw" priority />
            <div className="absolute inset-0" style={{ background: "linear-gradient(to right, rgba(0,0,0,0.88) 50%, rgba(0,0,0,0.3) 100%)" }} />
            <div className="relative z-10 mx-auto max-w-6xl px-6 py-20 text-white">
              {industry && (
                <p className="mb-3 text-xs font-bold uppercase tracking-[0.3em] text-white/50">{industry}</p>
              )}
              <h1 className="text-5xl font-black leading-tight tracking-tight max-w-2xl md:text-7xl">{businessName}</h1>
              <p className="mt-4 max-w-lg text-xl text-white/70">{tagline}</p>
              <div className="mt-8 flex flex-wrap gap-3">
                <a href={primaryCtaUrl} className="rounded-xl px-7 py-4 text-sm font-black text-white transition-all hover:opacity-90"
                  style={{ background: accentColor }}>
                  {primaryCtaLabel}
                </a>
              </div>
            </div>
          </>
        ) : (
          <div className="relative z-10 mx-auto max-w-6xl px-6 py-20 w-full"
            style={{ background: `linear-gradient(135deg, ${accentColor}10 0%, transparent 70%)` }}>
            {industry && (
              <p className="mb-3 text-xs font-bold uppercase tracking-[0.3em] text-zinc-400">{industry}</p>
            )}
            <h1 className="text-5xl font-black leading-tight tracking-tight max-w-2xl md:text-7xl">{businessName}</h1>
            <p className="mt-4 max-w-lg text-xl text-zinc-500">{tagline}</p>
            <div className="mt-8">
              <a href={primaryCtaUrl} className="inline-block rounded-xl px-7 py-4 text-sm font-black text-white transition-all hover:opacity-90"
                style={{ background: accentColor }}>
                {primaryCtaLabel}
              </a>
            </div>
          </div>
        )}
      </section>

      {/* Stats bar */}
      <section className="border-y border-zinc-100 bg-zinc-50 px-6 py-10">
        <div className="mx-auto max-w-6xl flex flex-wrap items-center justify-center gap-x-16 gap-y-6">
          {founded && (
            <div className="text-center">
              <p className="text-4xl font-black text-zinc-900">Est. {founded}</p>
              <p className="text-xs text-zinc-400 uppercase tracking-wider mt-1">Founded</p>
            </div>
          )}
          {employeeCount && (
            <div className="text-center">
              <p className="text-4xl font-black text-zinc-900">{employeeCount}</p>
              <p className="text-xs text-zinc-400 uppercase tracking-wider mt-1">Team Size</p>
            </div>
          )}
          {certifications && certifications.slice(0, 3).map((c, i) => (
            <div key={i} className="text-center">
              <p className="text-sm font-bold text-zinc-700">✓ {c}</p>
            </div>
          ))}
        </div>
      </section>

      {/* About */}
      <section className="border-b border-zinc-100 px-6 py-16">
        <div className="mx-auto max-w-3xl text-center">
          <h2 className="text-3xl font-black mb-4">Who We Are</h2>
          <p className="text-lg leading-relaxed text-zinc-500">{description}</p>
        </div>
      </section>

      {/* Services */}
      <section id="services" className="border-b border-zinc-100 px-6 py-20">
        <div className="mx-auto max-w-6xl">
          <div className="mb-12 text-center">
            <h2 className="text-4xl font-black">Our Solutions</h2>
          </div>
          <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
            {services.map((s, i) => (
              <div key={i} className={`group relative overflow-hidden rounded-2xl p-7 transition-all hover:shadow-2xl ${s.highlighted ? "text-white" : "border border-zinc-200 bg-white hover:border-zinc-300"}`}
                style={s.highlighted ? { background: `linear-gradient(135deg, ${accentColor}, ${accentColor}99)` } : {}}>
                <h3 className="text-xl font-black mb-1">{s.title}</h3>
                {s.price && <p className={`text-3xl font-black mb-3 ${s.highlighted ? "text-white" : "text-zinc-900"}`}>{s.price}</p>}
                <p className={`text-sm leading-relaxed ${s.highlighted ? "text-white/75" : "text-zinc-500"}`}>{s.description}</p>
                {s.features && (
                  <ul className="mt-4 space-y-2">
                    {s.features.map((f, j) => (
                      <li key={j} className={`flex items-center gap-2 text-sm ${s.highlighted ? "text-white/80" : "text-zinc-500"}`}>
                        <span className={s.highlighted ? "text-white/60" : ""} style={!s.highlighted ? { color: accentColor } : {}}>→</span> {f}
                      </li>
                    ))}
                  </ul>
                )}
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Testimonials — dark strip */}
      {testimonials && testimonials.length > 0 && (
        <section id="clients" className="border-b border-zinc-100 bg-zinc-950 px-6 py-20">
          <div className="mx-auto max-w-6xl">
            <h2 className="mb-12 text-4xl font-black text-white">Client Success</h2>
            <div className="grid gap-6 md:grid-cols-2">
              {testimonials.slice(0, 4).map((t, i) => (
                <div key={i} className="rounded-2xl border border-zinc-800 bg-zinc-900 p-6">
                  <StarRating rating={t.rating} />
                  <p className="mt-4 text-base leading-relaxed text-zinc-300 italic">&ldquo;{t.text}&rdquo;</p>
                  <div className="mt-5 flex items-center gap-3 border-t border-zinc-800 pt-4">
                    <div className="flex h-10 w-10 items-center justify-center rounded-full font-bold text-white"
                      style={{ background: accentColor }}>
                      {t.author.charAt(0)}
                    </div>
                    <div>
                      <p className="font-bold text-white">{t.author}</p>
                      {t.platform && <p className="text-xs text-zinc-500">{t.platform}</p>}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* Contact */}
      <section id="contact" className="px-6 py-20">
        <div className="mx-auto max-w-6xl grid gap-10 md:grid-cols-2">
          <div>
            <h2 className="mb-6 text-3xl font-black">Get in Touch</h2>
            <div className="space-y-3">
              {contacts.map((c, i) => (
                <a key={i} href={contactHref(c.type, c.value)}
                  className="flex items-center gap-3 text-zinc-500 hover:text-zinc-900 transition-colors">
                  <span className="text-lg">
                    {c.type === "email" ? "✉️" : c.type === "phone" ? "📱" : c.type === "address" ? "📍" : "🌐"}
                  </span>
                  {c.value}
                </a>
              ))}
            </div>
          </div>
          <div>
            <h2 className="mb-6 text-3xl font-black">Follow Us</h2>
            <div className="flex flex-wrap gap-3">
              {socialLinks.map((s, i) => (
                <a key={i} href={s.url} target="_blank" rel="noopener noreferrer"
                  className="rounded-xl border border-zinc-200 px-4 py-2.5 text-sm font-semibold text-zinc-600 hover:border-zinc-900 hover:text-zinc-900 transition-all">
                  {s.label ?? s.platform}
                </a>
              ))}
            </div>
          </div>
        </div>
      </section>

      <footer className="border-t border-zinc-100 bg-zinc-50 px-6 py-8 flex flex-wrap justify-between items-center gap-4">
        <span className="font-black text-zinc-900">{businessName}</span>
        <p className="text-xs text-zinc-300">PresenceCard</p>
      </footer>
    </main>
  );
}
